import java.util.Arrays;

// Java は常に値渡し。参照型は「参照の値」がコピーされて渡る
// ここを変えてみよう:reset の中で prices[1] = 777; も書いてみる
public class PassByValue {
    static void addTen(int n) {
        n = n + 10;                     // コピーを書き換えただけ
        System.out.println("  addTen の中: n = " + n);
    }

    static void clear(int[] prices) {
        prices[0] = 0;                  // 同じ配列の中身を変更 → 呼び出し元にも見える
    }

    static void reset(int[] prices) {
        prices = new int[]{9, 9};       // 仮引数の向き先を変えただけ → 呼び出し元は無関係
        System.out.println("  reset の中: " + Arrays.toString(prices));
    }

    public static void main(String[] args) {
        int x = 5;
        addTen(x);
        System.out.println("addTen の後: x = " + x);

        int[] p = {100, 200};
        clear(p);
        System.out.println("clear の後: " + Arrays.toString(p));
        reset(p);
        System.out.println("reset の後: " + Arrays.toString(p));
    }
}

// オーバーロードと可変長引数
// ここを変えてみよう:total(500, 3, 200) の 200 を消す / sum の引数を増やす・空にする
public class Overload {
    static int total(int price, int qty) {
        return total(price, qty, 0);    // 少ない版が多い版を呼ぶ
    }

    static int total(int price, int qty, int off) {
        return price * qty - off;
    }

    static double total(double price, int qty) {   // 引数の型が違えば別のメソッド
        return price * qty;
    }

    static int sum(int... nums) {       // nums の正体は int[]
        int s = 0;
        for (int n : nums) {
            s += n;
        }
        return s;
    }

    public static void main(String[] args) {
        System.out.println(total(500, 3));        // total(int, int)
        System.out.println(total(500, 3, 200));   // total(int, int, int)
        System.out.println(total(99.5, 2));       // total(double, int)
        System.out.println(sum());                // 0個でもOK
        System.out.println(sum(1, 2, 3, 4));
    }
}

// 再帰で階乗を計算する
// ここを変えてみよう:n を 20 や 21 にする(long の範囲を超えるとどうなる?)
// if の終了条件を消すと StackOverflowError になる
public class Factorial {
    static long factorial(int n) {
        if (n <= 1) {
            return 1;                   // 終了条件(これがないと永遠に潜る)
        }
        return n * factorial(n - 1);    // 自分自身を呼ぶ
    }

    public static void main(String[] args) {
        int n = 5;
        System.out.println(n + "! = " + factorial(n));
        for (int i = 1; i <= 10; i++) {
            System.out.print(factorial(i) + " ");
        }
        System.out.println();
    }
}

